int main() {
    readAll();
    int n = num();
    vector<int> coins(n), degree(n, 0);
    for (auto& c : coins) c = num();
    vector<vector<int>> adj(n);
    for (int i = 0; i < n - 1; i++) {
        int a = num(), b = num();
        adj[a].push_back(b), adj[b].push_back(a);
        degree[a]++, degree[b]++;
    }
    vector<char> alive(n, 1);
    long long remaining = n - 1;  // edges still in the tree
    // 1) Repeatedly cut leaves without a coin.
    vector<int> q;
    for (int i = 0; i < n; i++)
        if (degree[i] <= 1 && !coins[i]) q.push_back(i);
    for (size_t h = 0; h < q.size(); h++) {
        int u = q[h];
        if (!alive[u]) continue;
        alive[u] = 0;
        for (int v : adj[u])
            if (alive[v]) {
                remaining--;
                if (--degree[v] <= 1 && !coins[v]) q.push_back(v);
            }
    }
    // 2) Coins within distance 2 are collected from afar: strip two leaf layers.
    vector<int> layer;
    for (int i = 0; i < n; i++)
        if (alive[i] && degree[i] <= 1) layer.push_back(i);
    for (int round = 0; round < 2; round++) {
        vector<int> following;
        for (int u : layer) {
            alive[u] = 0;
            for (int v : adj[u])
                if (alive[v]) {
                    remaining--;
                    if (--degree[v] == 1) following.push_back(v);
                }
        }
        layer = following;
    }
    // Every remaining edge is walked twice.
    printf("%lld\n", 2 * max(0LL, remaining));
}

public class Main {
    static byte[] data;
    static int pos = 0;

    static boolean skipSpace() {
        while (pos < data.length && (data[pos] & 0xff) <= ' ') pos++;
        return pos < data.length;
    }

    static String token() {
        skipSpace();
        int s = pos;
        while (pos < data.length && (data[pos] & 0xff) > ' ') pos++;
        return new String(data, s, pos - s, java.nio.charset.StandardCharsets.UTF_8);
    }

    static long num() {
        skipSpace();
        boolean neg = false;
        if (pos < data.length && (data[pos] == '-' || data[pos] == '+')) neg = data[pos++] == '-';
        long v = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') v = v * 10 + (data[pos++] - '0');
        return neg ? -v : v;
    }

    public static void main(String[] args) throws Exception {
        data = System.in.readAllBytes();
        int n = (int) num();
        int[] coins = new int[n], degree = new int[n];
        for (int i = 0; i < n; i++) coins[i] = (int) num();
        int[] ea = new int[n - 1], eb = new int[n - 1];
        for (int i = 0; i < n - 1; i++) {
            ea[i] = (int) num();
            eb[i] = (int) num();
            degree[ea[i]]++;
            degree[eb[i]]++;
        }
        // Adjacency in CSR form.
        int[] start = new int[n + 1], fill = new int[n], adj = new int[2 * (n - 1)];
        for (int i = 0; i < n; i++) start[i + 1] = start[i] + degree[i];
        for (int i = 0; i < n - 1; i++) {
            adj[start[ea[i]] + fill[ea[i]]++] = eb[i];
            adj[start[eb[i]] + fill[eb[i]]++] = ea[i];
        }
        boolean[] alive = new boolean[n];
        java.util.Arrays.fill(alive, true);
        long remaining = n - 1;  // edges still in the tree
        // 1) Repeatedly cut leaves without a coin.
        int[] q = new int[2 * n + 1];
        int head = 0, tail = 0;
        for (int i = 0; i < n; i++)
            if (degree[i] <= 1 && coins[i] == 0) q[tail++] = i;
        while (head < tail) {
            int u = q[head++];
            if (!alive[u]) continue;
            alive[u] = false;
            for (int k = start[u]; k < start[u + 1]; k++) {
                int v = adj[k];
                if (alive[v]) {
                    remaining--;
                    if (--degree[v] <= 1 && coins[v] == 0) q[tail++] = v;
                }
            }
        }
        // 2) Coins within distance 2 are collected from afar: strip two leaf layers.
        int[] layer = new int[n];
        int size = 0;
        for (int i = 0; i < n; i++)
            if (alive[i] && degree[i] <= 1) layer[size++] = i;
        for (int round = 0; round < 2; round++) {
            int[] following = new int[n];
            int next = 0;
            for (int t = 0; t < size; t++) {
                int u = layer[t];
                alive[u] = false;
                for (int k = start[u]; k < start[u + 1]; k++) {
                    int v = adj[k];
                    if (alive[v]) {
                        remaining--;
                        if (--degree[v] == 1) following[next++] = v;
                    }
                }
            }
            layer = following;
            size = next;
        }
        // Every remaining edge is walked twice.
        System.out.println(2 * Math.max(0, remaining));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(num())
	coins, degree := make([]int64, n), make([]int, n)
	for i := range coins {
		coins[i] = num()
	}
	adj := make([][]int, n)
	for i := 0; i < n-1; i++ {
		a, b := int(num()), int(num())
		adj[a] = append(adj[a], b)
		adj[b] = append(adj[b], a)
		degree[a]++
		degree[b]++
	}
	alive := make([]bool, n)
	for i := range alive {
		alive[i] = true
	}
	remaining := int64(n - 1) // edges still in the tree
	// 1) Repeatedly cut leaves without a coin.
	q := []int{}
	for i := 0; i < n; i++ {
		if degree[i] <= 1 && coins[i] == 0 {
			q = append(q, i)
		}
	}
	for h := 0; h < len(q); h++ {
		u := q[h]
		if !alive[u] {
			continue
		}
		alive[u] = false
		for _, v := range adj[u] {
			if alive[v] {
				remaining--
				degree[v]--
				if degree[v] <= 1 && coins[v] == 0 {
					q = append(q, v)
				}
			}
		}
	}
	// 2) Coins within distance 2 are collected from afar: strip two leaf layers.
	layer := []int{}
	for i := 0; i < n; i++ {
		if alive[i] && degree[i] <= 1 {
			layer = append(layer, i)
		}
	}
	for round := 0; round < 2; round++ {
		following := []int{}
		for _, u := range layer {
			alive[u] = false
			for _, v := range adj[u] {
				if alive[v] {
					remaining--
					degree[v]--
					if degree[v] == 1 {
						following = append(following, v)
					}
				}
			}
		}
		layer = following
	}
	// Every remaining edge is walked twice.
	fmt.Println(2 * max(0, remaining))
}
